import { expect, test } from "bun:test";
import { Cart } from "./cart";

test("total sums price times quantity", () => {
  const cart = new Cart();
  cart.add({ sku: "mug", price: 1200, quantity: 2 });
  expect(cart.total()).toBe(2400);
});

