test("applyDiscount SAVE10 takes 10% off total", () => {
  const cart = new Cart();
  cart.add({ sku: "mug", price: 1200, quantity: 2 });
  cart.applyDiscount("SAVE10");
  expect(cart.total()).toBe(2160);
});

